import {platforms,platformById,journeys,stageGroup,validateWorkspaceUrl} from './platforms.mjs';
export function createWorkbench({state,api,esc,toast,modal,download,render,detail}){
 const $=s=>document.querySelector(s),ui={items:[],settings:[],selected:null,events:[],tab:'action',kind:'all',search:'',category:'All',platformSearch:''};
 const button=(label,action,extra='',cls='secondary')=>`<button class="${cls}" data-wb="${action}" ${extra}>${label}</button>`;
 const pill=(label,cls='')=>`<span class="pill ${cls}">${esc(label)}</span>`;
 const mark=p=>`<span class="platform-mark" style="--tint:${p.colour}33;--ink:#344b62" aria-hidden="true">${p.mark}</span>`;
 const stage=w=>journeys[w.kind].steps[w.stage],complete=w=>!stage(w);
 const overdue=w=>!complete(w)&&w.payload.due&&w.payload.due<new Date().toLocaleDateString('en-CA');
 const when=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-AU',{day:'numeric',month:'short'}):'No due date';
 const header=(title,sub,actions='')=>`<div class="page-heading"><div><p class="eyebrow">PHILLIP RILEY / WORKSPACE</p><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;
 const notice=()=>`<div class="integration-note"><span class="mode-dot"></span><div><strong>Rehearsal workspace.</strong> Use fictional case details. Work items, notes and reviews are saved here; live platforms are not connected.</div></div>`;
 const setting=id=>ui.settings.find(s=>s.platform_id===id),selected=()=>ui.items.find(w=>w.id===ui.selected);
 const canSave=()=>state.me?true:(toast(state.authUnavailable?'Staff sign-in is pending setup. You can browse the public guides.':'Sign in to save your work.'),false);
 const toolsFor=w=>(stage(w)?.tools||['jobadder']).map(platformById);
 function platformButtons(ids){return `<div class="stage-platforms">${ids.map(id=>{const p=platformById(id),s=setting(id)?.payload;return s?.workspaceUrl?`<a class="platform-link" href="${esc(s.workspaceUrl)}" target="_blank" rel="noopener noreferrer">${mark(p)} ${p.name} ↗</a>`:button(mark(p)+' '+p.name,'platform',`data-id="${id}"`,'platform-link');}).join('')}</div>`;}
 const progress=w=>`<div class="progress-track" aria-label="${w.stage} of ${journeys[w.kind].steps.length} stages complete"><span style="width:${w.stage/journeys[w.kind].steps.length*100}%"></span></div>`;
 function row(w){return `<div class="work-row">${mark(toolsFor(w)[0])}<div class="grow"><strong>${esc(w.title)}</strong><small>${esc(stage(w)?.name||'Checklist complete')} · ${esc(w.payload.assignee)}</small></div><small class="${overdue(w)?'due':''}">${overdue(w)?'Overdue · ':''}${when(w.payload.due)}</small>${button('Open','open',`data-id="${w.id}"`,'small secondary')}</div>`;}
 function overview(){const pending=state.records.flatMap(r=>r.payload.fields).filter(f=>['pending','held'].includes(f.decision)).length,active=ui.items.filter(w=>!complete(w)),due=active.filter(overdue),next=[...active].sort((a,b)=>(a.payload.due||'9999').localeCompare(b.payload.due||'9999')),pinned=platforms.filter(p=>setting(p.id)?.payload.pinned),shortcuts=pinned.length?pinned:platforms.filter(p=>['jobadder','corecruit','roi','lusha'].includes(p.id));
  return header('Recruitment workspace','Phillip Riley’s workflows, evidence reviews and platform shortcuts in one place.',button('+ New work item','new','',''))+`<div class="top-summary"><section class="focus-panel"><div class="tags">${pill('JobAdder at the centre')}${pill('Evidence before updates')}</div><p class="eyebrow">YOUR RECRUITMENT DESK</p><h2>${active.length?`${active.length} ${active.length===1?'case':'cases'} moving. Keep the next step clear.`:'Make the next handoff a good one.'}</h2><p>Carry the source, review and outcome from the first conversation to placement. Keep specialist work in the tools built for it.</p><a class="button" href="#work">Open your work board →</a></section><section class="next-panel"><h2>Your review inbox</h2><p><strong>${pending}</strong> fields need a decision across <strong>${state.records.length}</strong> saved records.</p><p>Check the source and keep the decision with the record. Your access determines which reviews appear here.</p><a class="button secondary" href="#queue">Review enrichment →</a></section></div><div class="stats metrics-four">${[['Active work',active.length,'Saved workflow cases'],['Overdue',due.length,'Open cases past their due date'],['Pending reviews',pending,'Fields awaiting a decision'],['Live connections','0','Platform access not configured']].map(([l,v,n])=>`<article><span>${l}</span><strong>${v}</strong><small>${n}</small></article>`).join('')}</div><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><h2>Next up</h2><a href="#work" class="section-kicker">View board →</a></div>${next.length?next.slice(0,5).map(row).join(''):`<div class="empty"><h3>Your desk is ready.</h3><p>Create a work item or explore three clearly labelled examples.</p><div class="actions">${button('Create work item','new','','')}${button('Load example workflows','examples')}</div></div>`}</section><section class="panel"><div class="panel-head"><h2>Your platform shortcuts</h2><a href="#platforms" class="section-kicker">Manage platforms →</a></div><div class="platform-strip">${shortcuts.map(p=>button(`${mark(p)}<span><strong>${p.name}</strong><small>${setting(p.id)?.payload.workspaceUrl?'Workspace link saved':'Set up your shortcut'}</small></span>`,'platform',`data-id="${p.id}"`,'platform-shortcut')).join('')}</div></section></div><section class="panel"><div class="panel-head"><h2>Built around PRG’s workflow</h2></div><div class="route-bands">${[['Conversation → record',['8x8','corecruit','jobadder'],'Capture the call in the existing tools. Review evidence before changing the record.'],['Research → client follow-up',['salesnav','lusha','jobadder'],'Keep project signals, verified contact details and an owned next step together.'],['Placement → handoff',['jobadder','zapier','xero'],'Prepare one handoff for the existing notifications, finance and reporting paths.']].map(([h,ids,t])=>`<div class="route-band"><h3>${h}</h3><div class="route-nodes">${ids.map((id,i)=>(i?' <span>→</span> ':'')+mark(platformById(id))).join('')}</div><p>${t}</p></div>`).join('')}</div><p class="panel-note">Native paths are documented in PRG’s supplied overview. Confirm their live configuration with the tool owner.</p></section></div>`+notice();
 }
 function board(){const matches=ui.items.filter(w=>(ui.kind==='all'||w.kind===ui.kind)&&`${w.title} ${w.payload.assignee} ${w.payload.summary}`.toLowerCase().includes(ui.search.toLowerCase()));return header('Work board','Keep the owner, next step and evidence with the same case.',button('Load examples','examples')+button('+ New work item','new','',''))+notice()+`<div class="work-header"><label>Find a case<input id="wb-search" value="${esc(ui.search)}" placeholder="Title, owner or context"></label><label>Workflow<select id="wb-kind"><option value="all">All workflows</option>${Object.entries(journeys).map(([k,j])=>`<option value="${k}" ${ui.kind===k?'selected':''}>${j.name}</option>`).join('')}</select></label><span class="small-label">${matches.length} ${matches.length===1?'case':'cases'} · saved to your account</span></div><div class="board">${['Prepare','Review & enrich','Handoff','Complete'].map((name,i)=>{const items=matches.filter(w=>stageGroup(w)===i);return `<section class="board-column"><div class="board-heading">${name}<span>${items.length}</span></div>${items.map(w=>`<article class="work-card">${pill(journeys[w.kind].short,journeys[w.kind].colour)}${w.payload.priority==='high'?' '+pill('High priority','amber'):''}<h3>${esc(w.title)}</h3><p class="muted">${esc(stage(w)?.name||'Checklist complete')}</p><div class="route-nodes">${toolsFor(w).slice(0,4).map(mark).join('')}</div>${progress(w)}<div class="card-meta"><span>${esc(w.payload.assignee)}</span><span class="${overdue(w)?'due':''}">${overdue(w)?'Overdue · ':''}${when(w.payload.due)}</span></div>${button('Open case →','open',`data-id="${w.id}"`)}</article>`).join('')||'<p class="board-empty">No cases in this stage.</p>'}</section>`;}).join('')}</div>`;}
 function workDetail(w){const j=journeys[w.kind],s=stage(w),linked=state.records.find(r=>r.id===w.record_id);let body='';
  if(ui.tab==='action')body=`<section class="panel"><div class="panel-head"><div><p class="eyebrow">${s?'CURRENT STAGE':'ALL STAGES RECORDED'}</p><h2>${esc(s?.name||'Checklist complete')}</h2></div>${pill(s?`${w.stage+1} / ${j.steps.length}`:'Complete',s?'blue':'green')}</div><p>${esc(s?.output||'Review the handoff packet and follow the authoritative source process before any external action.')}</p>${s?platformButtons(s.tools)+`<form id="wb-progress-form" data-id="${w.id}" data-version="${w.version}"><div class="action-checks">${s.checks.map((c,i)=>`<label class="check"><input name="check-${i}" type="checkbox" ${w.payload.checks[w.stage]?.[i]?'checked':''}>${esc(c)}</label>`).join('')}</div><label>Evidence / outcome reference<textarea name="evidence" maxlength="2000" placeholder="Use a fictional source reference and concise outcome for this rehearsal.">${esc(w.payload.evidence[w.stage]||'')}</textarea></label><p class="panel-note">These are recorded human checkpoints. Ticking a box does not verify compliance, approve a candidate or update another platform.</p><p class="form-error error" role="alert"></p><div class="actions"><button name="save" value="draft" class="secondary">Save checkpoints</button><button name="save" value="advance">Complete stage →</button></div></form>`:''}</section><section class="panel"><h2>Case context</h2><p class="preserve-lines">${esc(w.payload.summary)||'No context recorded yet.'}</p><p class="panel-note">Assignee: ${esc(w.payload.assignee)} · Due: ${when(w.payload.due)}. The assignee is a label; this item is private to your account and no invitation or notification is sent.</p></section>`;
  if(ui.tab==='enrichment')body=linked?detail(linked):`<section class="panel empty"><h2>Keep the field review with this case.</h2><p>Link a matching enrichment record you own. Your source checks and field decisions will appear here.</p><div class="actions">${button('Link an existing record','edit',`data-id="${w.id}"`,'')}<a class="button secondary" href="#queue">Open enrichment queue</a></div></section>`;
  if(ui.tab==='activity')body=`<section class="panel"><h2>Conversation notes & activity</h2><p>Save a synthetic outcome from the tool you used. It stays with this case.</p><form id="wb-note-form" data-id="${w.id}" data-version="${w.version}"><label>Source platform<select name="platform"><option value="">General note</option>${platforms.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><label>Outcome / next action<textarea name="note" required maxlength="4000" placeholder="What was learned? What happens next?"></textarea></label><p class="form-error error" role="alert"></p><button>Save note</button></form><hr>${[...ui.events].reverse().map(e=>`<article class="activity-entry"><small>${esc(e.kind.replaceAll('_',' '))} · ${esc(e.actor)} · ${new Date(e.created_at).toLocaleString('en-AU')}</small><p>${esc(e.note)}</p></article>`).join('')}</section>`;
  if(ui.tab==='handoff')body=`<section class="panel"><div class="panel-head"><h2>One handoff, with the context intact.</h2>${pill(complete(w)?'Checklist complete':'In progress',complete(w)?'green':'amber')}</div><p>The packet brings the case, completed checkpoints, evidence and activity history together. It is available at any stage and clearly states what remains incomplete.</p><pre class="handoff-preview">${esc(handoffText(w))}</pre><div class="actions">${button('Download handoff packet','packet',`data-id="${w.id}"`,'')}${button('Download message draft','message',`data-id="${w.id}"`)}</div><p class="panel-note">Draft only. No Chat message, Mailchimp send, invoice or ATS update is triggered. The existing placement automation remains the preferred delivery path.</p>${platformButtons(w.kind==='contract'?['jobadder','astute','xero','oneup']:w.kind==='client'?['jobadder','8x8']:['jobadder','zapier','gchat','mailchimp','xero','oneup'])}</section><section class="panel"><h2>Checkpoint history</h2>${j.steps.map((s,i)=>`<div class="activity-entry"><strong>${i+1}. ${esc(s.name)}</strong> ${pill(i<w.stage?'Recorded':i===w.stage?'Current':'Not started',i<w.stage?'green':'')}<p>${esc(w.payload.evidence[i]||'No evidence reference saved.')}</p></div>`).join('')}</section>`;
  return header(esc(w.title),`${j.name} · ${esc(w.payload.assignee)} · ${when(w.payload.due)}`,button('← All cases','back')+button('Edit details','edit',`data-id="${w.id}"`))+`<div class="work-detail-layout"><aside><div class="step-list">${j.steps.map((s,i)=>`<div class="step-item ${i<w.stage?'done':i===w.stage?'current':''}"><span class="step-num">${i<w.stage?'✓':i+1}</span><div><strong>${esc(s.name)}</strong><small>${i<w.stage?'Checkpoint recorded':i===w.stage?'Current stage':'Upcoming'}</small></div></div>`).join('')}</div><p class="panel-note">${j.description}</p><a href="#workflow">View source process →</a></aside><div><div class="work-tabs" role="group" aria-label="Case view">${[['action','Next action'],['enrichment','Enrichment'],['activity','Notes & activity'],['handoff','Handoff']].map(([id,label])=>button(label,'tab',`data-tab="${id}" aria-pressed="${ui.tab===id}"`,ui.tab===id?'active':'')).join('')}</div>${body}</div></div>`;
 }
 function handoffText(w){return `DRAFT · SYNTHETIC REHEARSAL\n${w.title}\nWorkflow: ${journeys[w.kind].name}\nOwner label: ${w.payload.assignee}\nNext: ${stage(w)?.name||'Review completed checklist'}\nDue: ${w.payload.due||'Not set'}\nRecorded stages: ${w.stage}/${journeys[w.kind].steps.length}\nContext: ${w.payload.summary||'Not recorded'}\nLatest evidence: ${w.payload.evidence[Math.max(0,w.stage-1)]||'Not recorded'}\n\nReview the source system before acting. This draft has not been sent.`;}
 function hub(){const list=platforms.filter(p=>(ui.category==='All'||p.category===ui.category)&&(p.name+' '+p.feature).toLowerCase().includes(ui.platformSearch.toLowerCase()));return header('Your platforms. One place to work.','Use each tool for what it does best. Keep the case and its next step together.',`<a class="button secondary" href="#stack">Full stack review</a>`)+`<div class="integration-note"><div><strong>Shortcuts and integration plans are available. Live connections: 0.</strong><br>Save an approved workspace link, pin the tools you use and track what is needed for a supported connection. Links do not synchronise data.</div></div><div class="work-header"><label>Find a platform or capability<input id="wb-platform-search" placeholder="Try call notes, contact or invoice" value="${esc(ui.platformSearch)}"></label></div><div class="platform-filter" role="group" aria-label="Platform category">${['All',...new Set(platforms.map(p=>p.category))].map(c=>button(c,'category',`data-category="${c}" aria-pressed="${ui.category===c}"`,ui.category===c?'active':'')).join('')}</div><div class="platform-grid">${list.map(p=>`<article class="platform-card"><div class="platform-title">${mark(p)}<div><h3>${p.name}</h3><span class="capability">${p.category}${setting(p.id)?.payload.pinned?' · Pinned':''}</span></div></div><p>${p.feature}</p><small class="muted">${setting(p.id)?.payload.workspaceUrl?'Shortcut configured · ':''}Not connected</small><div class="actions">${button('View workflow & setup','platform',`data-id="${p.id}"`,'small secondary')}${setting(p.id)?.payload.workspaceUrl?`<a href="${esc(setting(p.id).payload.workspaceUrl)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${p.name}">Open ↗</a>`:''}</div></article>`).join('')||'<section class="panel"><h2>No platforms match.</h2><p>Try another term or category.</p></section>'}</div>`;}
 function edit(w,kind='permanent'){kind=w?.kind||kind;modal(`<h2>${w?'Edit work item':'Create a work item'}</h2><p>Keep fictional case details, its next action and evidence together.</p><form id="wb-item-form" data-id="${w?.id||''}" data-version="${w?.version||0}"><div class="form-grid"><label class="full">Case title<input name="title" required maxlength="160" placeholder="e.g. Demo · Grid connection engineer" value="${esc(w?.title||'')}"></label><label>Workflow<select name="kind" id="wb-item-kind" ${w?'disabled':''}>${Object.entries(journeys).map(([id,j])=>`<option value="${id}" ${id===kind?'selected':''}>${j.name}</option>`).join('')}</select></label><label>Assignee label<input name="assignee" maxlength="120" value="${esc(w?.payload.assignee||'Me')}"></label><label>Due date<input name="due" type="date" value="${esc(w?.payload.due||'')}"></label><label>Priority<select name="priority"><option value="normal">Normal</option><option value="high" ${w?.payload.priority==='high'?'selected':''}>High</option></select></label><label class="full">Linked enrichment record<select name="recordId" id="wb-record-link">${recordOptions(kind,w?.record_id)}</select></label><label class="full">Context / desired outcome<textarea name="summary" maxlength="2000">${esc(w?.payload.summary||'')}</textarea></label></div><p class="panel-note">Only your matching records are linkable. Assignee labels do not grant access or send notifications. ${w?'Changing a linked record resets its capture/enrichment and downstream stage checkpoints.':''}</p>${!w?'<label class="check"><input name="syntheticOnly" type="checkbox" required>I am using fictional case details.</label>':''}<button>${w?'Save details':'Create work item'}</button></form>`);}
 function recordOptions(kind,id){return '<option value="">No linked record</option>'+state.records.filter(r=>r.owner_id===state.me?.id&&(kind==='client'?r.kind==='contact':r.kind==='candidate'&&r.workflow===kind)).map(r=>`<option value="${r.id}" ${r.id===id?'selected':''}>${esc(r.name)} · ${esc(r.external_id)}</option>`).join('');}
 function platformDialog(id){const p=platformById(id),s=setting(id),x=s?.payload||{};modal(`<div class="platform-title">${mark(p)}<h2>${p.name}</h2></div>${pill('Not connected','amber')}<div class="feature-block"><h3>What this platform brings</h3><p>${p.feature}</p></div><div class="feature-block"><h3>How it fits here</h3><p>${p.inside}</p></div><div class="feature-block"><h3>Connection route to validate</h3><p>${p.connection}</p>${p.source?`<p><a href="${p.source}" target="_blank" rel="noopener noreferrer">Official platform reference ↗</a></p>`:''}</div><form id="wb-platform-form" data-id="${id}" data-version="${s?.version||0}"><label>Approved workspace URL<input type="url" name="workspaceUrl" value="${esc(x.workspaceUrl||'')}" placeholder="https://…" ${p.domains.length?'':'disabled'}></label><p class="panel-note">${p.domains.length?'Allowed domains: '+p.domains.join(', ')+'. Save a normal workspace URL without secrets or authentication tokens.':'Domain and access route need confirmation before a shortcut can be saved.'}</p><div class="form-grid"><label>System owner<input name="owner" maxlength="120" value="${esc(x.owner||'')}"></label><label class="check"><input name="pinned" type="checkbox" ${x.pinned?'checked':''}>Pin to overview</label></div><label>Integration notes<textarea name="notes" maxlength="2000" placeholder="Scope, licensing question or next action. No credentials.">${esc(x.notes||'')}</textarea></label><details><summary>Integration readiness checklist</summary><div class="action-checks">${[['owner','System owner and purpose agreed'],['access','Approved account / API entitlement confirmed'],['mapping','Fields, permissions and existing native path checked'],['test','Sandbox validation and recovery plan completed']].map(([k,l])=>`<label class="check"><input name="ready-${k}" type="checkbox" ${x.readiness?.[k]?'checked':''}>${l}</label>`).join('')}</div><p class="panel-note">Planning only. These checkboxes do not enable a connection or verify access.</p></details><div class="actions"><button>Save platform setup</button>${x.workspaceUrl?`<a class="button secondary" target="_blank" rel="noopener noreferrer" href="${esc(x.workspaceUrl)}">Open workspace ↗</a>`:''}</div></form>`);}
 const pages=[['home','Workspace overview'],['discovery','Team needs & usage'],['opportunities','Opportunity register'],['reviews','Agent reviews & trials'],['options','Four-path comparison'],['roadmap','Roadmap & ownership'],['work','Work board'],['queue','Enrichment review'],['platforms','Platform hub'],['workflow','Process map'],['costs','Cost review'],['pilot','Pilot results'],['evidence','Sources & decisions'],['guide','Staff guide']];
 function searchResults(q=''){const term=q.toLowerCase();return [...pages.map(([id,name])=>({name,type:'Page',action:'go',id})),...ui.items.map(w=>({name:w.title,type:journeys[w.kind].short,action:'open',id:w.id})),...state.records.map(r=>({name:r.name+' · '+r.external_id,type:'Enrichment record',action:'record',id:r.id})),...platforms.map(p=>({name:p.name,type:'Platform',action:'platform',id:p.id}))].filter(x=>(x.name+' '+x.type).toLowerCase().includes(term)).slice(0,14).map(x=>button(`<span>${esc(x.name)}</span><small>${esc(x.type)}</small>`,x.action,`data-id="${x.id}"`,'command-result')).join('')||'<p>No matches. Try a platform name or case title.</p>';}
 function command(){modal(`<h2>Search your workspace</h2><label>Find a case, record or platform<input id="wb-command-search" placeholder="Type to search…" autocomplete="off"></label><div class="command-list" id="wb-command-results">${searchResults()}</div>`);$('#wb-command-search').focus();}
 async function open(id){ui.selected=id;ui.tab='action';$('#modal').close();if(location.hash==='#work')await render();else location.hash='work';}
 async function load(){if(!state.me)return;const d=await api('/workbench');ui.items=d.items;ui.settings=d.settings;if(ui.selected){const found=ui.items.find(w=>w.id===ui.selected);if(found){const d=await api('/workbench/items/'+found.id);ui.events=d.events;ui.items=ui.items.map(w=>w.id===found.id?d.item:w);}else ui.selected=null;}}
 function repaint(){const v=state.route==='home'?overview():state.route==='platforms'?hub():selected()?workDetail(selected()):board();$('#main').innerHTML=v;}
 document.addEventListener('click',async event=>{const b=event.target.closest('[data-wb]');if(!b)return;const a=b.dataset.wb;try{
  if(a==='command')return command();if(a==='go'){$('#modal').close();location.hash=b.dataset.id;return;}
  if(a==='record'){state.selected=b.dataset.id;state.search='';state.kind='all';state.status='all';$('#modal').close();if(location.hash==='#queue')await render();else location.hash='queue';return;}
  if(a==='open')return await open(b.dataset.id);if(a==='new'){if(canSave())edit();return;}if(a==='edit'){if(canSave())edit(ui.items.find(w=>w.id===b.dataset.id));return;}
  if(a==='back'){ui.selected=null;return repaint();}if(a==='tab'){ui.tab=b.dataset.tab;return repaint();}if(a==='platform')return platformDialog(b.dataset.id);if(a==='category'){ui.category=b.dataset.category;return repaint();}
  if(!canSave())return;b.disabled=true;
  if(a==='examples'){const examples=[['Demo · Grid connection engineer','permanent','Review a fictional engineer’s source evidence and prepare a placement handoff.'],['Demo · BESS site contractor','contract','Keep the fictional work order, enrichment review and Operations handoff together.'],['Demo · Renewable project account','client','Research a fictional project signal and review business-contact evidence.']];for(const [title,kind,summary]of examples)if(!ui.items.some(w=>w.title===title))await api('/workbench/items',{method:'POST',body:{title,kind,summary,syntheticOnly:true}});toast('Example workflows saved. No live platform activity occurred.');await render();}
  if(a==='packet'){const w=ui.items.find(w=>w.id===b.dataset.id),d=await api(`/workbench/items/${w.id}/packet`,{method:'POST',body:{version:w.version}});download('prg-work-handoff.json',d.packet);toast('Handoff downloaded. Nothing was sent to another platform.');await render();}
  if(a==='message'){download('prg-handoff-draft.txt',handoffText(ui.items.find(w=>w.id===b.dataset.id)),'text/plain');toast('Draft downloaded for review. Nothing has been sent.');}
 }catch(e){if($('#modal').open)$('#modal-error').textContent=e.message;else toast(e.message);}finally{if(b.isConnected)b.disabled=false;}});
 document.addEventListener('submit',async event=>{const f=event.target;if(!f.id.startsWith('wb-'))return;event.preventDefault();if(!canSave())return;const fd=new FormData(f),buttons=[...f.querySelectorAll('button')],err=f.querySelector('.form-error')||$('#modal-error');if(err)err.textContent='';buttons.forEach(b=>b.disabled=true);try{
  const id=f.dataset.id,version=Number(f.dataset.version);let item;
  if(f.id==='wb-item-form'){const old=ui.items.find(w=>w.id===id),v={...Object.fromEntries(fd),kind:old?.kind||fd.get('kind'),version,syntheticOnly:fd.has('syntheticOnly')};const d=await api('/workbench/items'+(id?'/'+id:''),{method:id?'PATCH':'POST',body:v});item=d.item;ui.selected=item.id;}
  if(f.id==='wb-progress-form'){const w=ui.items.find(w=>w.id===id);await api(`/workbench/items/${id}/progress`,{method:'POST',body:{version,checks:stage(w).checks.map((_,i)=>fd.has('check-'+i)),evidence:fd.get('evidence'),advance:event.submitter?.value==='advance'}});}
  if(f.id==='wb-note-form')await api(`/workbench/items/${id}/note`,{method:'POST',body:{version,note:fd.get('note'),platform:fd.get('platform')}});
  if(f.id==='wb-platform-form'){const v={...Object.fromEntries(fd),version,workspaceUrl:validateWorkspaceUrl(String(fd.get('workspaceUrl')||''),platformById(id)),pinned:fd.has('pinned'),readiness:Object.fromEntries(['owner','access','mapping','test'].map(k=>[k,fd.has('ready-'+k)]))};await api('/workbench/platforms/'+id,{method:'PUT',body:v});}
  $('#modal').close();toast('Saved to your workspace.');if(item&&location.hash!=='#work')location.hash='work';else await render();
 }catch(e){if(err)err.textContent=e.message;else toast(e.message);}finally{buttons.forEach(b=>{if(b.isConnected)b.disabled=false;});}});
 document.addEventListener('input',event=>{const e=event.target;if(e.id==='wb-command-search'){$('#wb-command-results').innerHTML=searchResults(e.value);return;}const k=e.id==='wb-search'?'search':e.id==='wb-platform-search'?'platformSearch':null;if(k){ui[k]=e.value;const pos=e.selectionStart,id=e.id;repaint();$('#'+id).focus();$('#'+id).setSelectionRange(pos,pos);}});
 document.addEventListener('change',event=>{if(event.target.id==='wb-kind'){ui.kind=event.target.value;repaint();}if(event.target.id==='wb-item-kind')$('#wb-record-link').innerHTML=recordOptions(event.target.value);});
 document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();command();}});
 return {load,view:route=>route==='home'?overview():route==='platforms'?hub():selected()?workDetail(selected()):board()};
}
